---@class UIActivityPtNode     
                       
local UIActivityPtNode = Class('UIActivityPtNode')

function UIActivityPtNode:__init()
    self._data = nil
end

function UIActivityPtNode:__delete()
    self._data = nil
end

function UIActivityPtNode:Awake()
    SetButtonAction(self.BtnGroup, Bind(self, self.OnClick))
end

function UIActivityPtNode:Refresh(data, cb)
    if not data then
        return
    end
    self._data = data
    self._cb = cb

    ActivityPtComponent:OverseaActivityPtQuestHomeReq(self._data.id, function()
        self:FillSelf()
    end)
end

function UIActivityPtNode:FillSelf()
    local startTime = self._data.startTime
    local closeTime = self._data.closeTime
    local endTime = self._data.endTime

    CfUtils.FillText(self.TxtTime, ActivityUtils.ConventActivityDurationTime(startTime, endTime))
    CfUtils.FillText(self.Text, self._data.detail)

    CfUtils.FillText(self.TextTime2, ActivityUtils.ConventLeftTimeText(self._data.endTime))
    
    local t = ActivityPtComponent:GetActivityConf()
    if self.BossDrawingNode then
        local vo = ActivityPtUtils.GetActivityPtPlanVo(t.id)
        vo = CardConfMgr:GetInstance():GetCardByRefId(vo.cardId)
        self.BossDrawingNode:Execute(checkNumber(vo.defaultSkin) , -1, -1 , "hdCardDrawing")
        KTool.SetActive(self.BossDrawingNode.gameObject , true)
    end
    self:StartTimeDown()
     -- 网络标题
     local titleImgUrl = checkString(self._data.titleImage)
     if string.len(titleImgUrl) > 0 then
         CfUtils.FillWebRawImage(self.ImgTitle, titleImgUrl)
     end
end

function UIActivityPtNode:StartTimeDown()
    if not isNull(self._timeDown) then
        CDTimerModule.GetInstance():RemoveCD(self._timeDown)
        self._timeDown = nil
    end
    self._timeDown = CDTimerModule.GetInstance():AddCD(1, function(count, id)
        CfUtils.FillText(self.TextTime2, ActivityUtils.ConventLeftTimeText(self._data.endTime))
    end, CountDownTime, false, true)
end

function UIActivityPtNode:OnClick()
    KCookie.Set("UIActivityPtNodeEntry", 1)
    local CriWareUtils = import('Game.Entry.CriWareUtilsFix')
    local t = ActivityPtComponent:GetActivityConf()
    CriWareUtils.PlayMusicById(t.openSound)
    xRecord.record('6-005', string.format('enter_activity_page_%d', checkInt(self._data.id)))
    local vo = ActivityPtUtils.GetFirstPlotId(t.id)
    local isShowFirst = ActivityPtUtils.IsPassQuest(vo.id)
    if not isShowFirst then
        ActivityPtComponent:OverseaActivityPtQuestPlotReq(self._data.id, vo.id, function(rewards)
            self:PlayPlot(vo, function()
                UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = rewards, cb = function()
                    UIModule.OpenDialog({ id = Constants.UITypeIds.UIActivityPtMainDialog, parameters = { activityUuid = self._data.id } }, {
                        { id = Constants.UITypeIds.UIActivityMainDialog },
                    })
                end } })
            end)
        end)
    else 
        UIModule.OpenDialog({ id = Constants.UITypeIds.UIActivityPtMainDialog, parameters = { activityUuid = self._data.id } }, {
            { id = Constants.UITypeIds.UIActivityMainDialog },
        })
    end
end
---播放剧情
function UIActivityPtNode:PlayPlot(vo, endCb)
    if not vo then
        return
    end
    if self._isPlayPlot then
        return
    end
    self._isPlayPlot = true
    local plotIds = CfUtils.Split(vo.storyId)
    if not plotIds then
        GameUtils.Toast(localize("该关卡没有剧情参数"))
        self._isPlayPlot = false
        return
    end
    
    self._curPlotIndex = 1
    self:PlayingPlot(plotIds, vo, endCb)
end

---剧情播放中
function UIActivityPtNode:PlayingPlot(plotIds, vo, endCb)
    local co = cs_coroutine.start(function()
        ::start::
        local wait = true
        ChapterUtils.ProcessChapter(checkNumber(plotIds[self._curPlotIndex]), function(go)
            self._plotGo = go
        end, function()
            --所有的播完结束
            wait = false
        end)

        while wait do
            coroutine.yield()
        end

        KTool.SafeDelete(self._plotGo)

        --dispose
        coroutine.yield()
        
        if self._curPlotIndex >= table.count(plotIds) then
            -- GameUtils.PlayMainBGM()
            if endCb then
                endCb()
            end

            self._isPlayPlot = false
        else
            self._curPlotIndex = self._curPlotIndex + 1
            goto start
        end
    end)
end

function UIActivityPtNode:PlanyAniByName(name)
end

function UIActivityPtNode:OnDestroy()
    if not isNull(self._timeDown) then
        CDTimerModule.GetInstance():RemoveCD(self._timeDown)
        self._timeDown = nil
    end
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return UIActivityPtNode
